#!/usr/bin/env bash
# Generated by mountaya/ai (scripts/apply.mjs). Edit .agents/manifest.json instead.
#
# What every release script shares (ai/workspace/baseline.json, `release`): whether CI passed on a
# commit, where a tag stands on Entire and on the mirror, a tag's notes from CHANGELOG.md, the push
# of a tag alone, the wait for the mirror, what already passed here on a commit, the lock gate
# respects, and the credentials the macOS Keychain holds. Each step reads where it stands from the
# remotes, the registries and the clone, so a release run again resumes where it stopped.
#
# Sourced, never executed, after lib/common.sh: . "$(dirname "$0")/lib/release.sh"
# bash 3.2, because macOS still ships it as /bin/bash, and safe under `set -euo pipefail`.

RELEASE_REPO='sdk-swift'
RELEASE_KEY='et/mountaya/sdk-swift'
# The read-only mirror on GitHub, which mirror.yml pushes every release tag to from Entire, then
# makes its GitHub Release. RELEASE_MIRROR_URL names another, a stand-in for a test.
RELEASE_MIRROR="$(printf '%s' "$(printenv RELEASE_MIRROR_URL || echo 'https://github.com/mountaya/sdk-swift')" | sed 's#/$##')"
RELEASE_KEYCHAIN_SERVICE='mountaya-release'

# release_git_dir: the git directory every worktree of the clone shares, where a release keeps
# what passed on a commit and its lock.
release_git_dir() { git rev-parse --path-format=absolute --git-common-dir; }

# release_refuse <text>: one refusal, with what to do; release_refused lists them all and stops.
release_refusals=()
release_refuse() { release_refusals+=("$1"); }
release_refused() {
  [ "${#release_refusals[@]}" -gt 0 ] || return 0
  {
    echo ""
    echo "${PF_RED}${PF_BOLD}✗ The release of $1 is refused.${PF_RESET}"
    for refusal in "${release_refusals[@]}"; do
      echo ""
      echo "$refusal"
    done
    echo ""
  } >&2
  exit 1
}

# release_is_version <text>: MAJOR.MINOR.PATCH, each a number with no leading zero.
release_is_version() { printf '%s\n' "$1" | grep -Eq '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'; }

# release_newer <a> <b>: whether version a comes after version b.
release_newer() {
  local a1 a2 a3 b1 b2 b3
  IFS=. read -r a1 a2 a3 <<<"$1"
  IFS=. read -r b1 b2 b3 <<<"$2"
  [ "$a1" -gt "$b1" ] && return 0
  [ "$a1" -lt "$b1" ] && return 1
  [ "$a2" -gt "$b2" ] && return 0
  [ "$a2" -lt "$b2" ] && return 1
  [ "$a3" -gt "$b3" ]
}

# release_checks <remote> <version>: the refusals every release of a `v<version>` tag makes before
# it does anything. The version is MAJOR.MINOR.PATCH; the tree is a clean clone on `main` at the
# commit the remote's `main` is at, on which CI finished green; `v<version>` is absent, or already
# on this commit where a release stopped after making it, here, on Entire and on the mirror; and
# no `v*` tag of any of them names a version this one is not newer than. Sets $release_head.
release_checks() {
  local remote="$1" version="$2" tag="v$2" toplevel branch answer main entire_tag here_tag mirror_tag existing refusal
  toplevel="$(git rev-parse --show-toplevel 2>/dev/null || true)"
  [ -n "$toplevel" ] && [ "$(cd "$toplevel" && pwd -P)" = "$(pwd -P)" ] \
    || die "$(pwd -P) is no git repository, so there is nothing to tag." "Release from a clone: entire repo clone /$RELEASE_KEY"
  release_head="$(git rev-parse HEAD)"
  release_is_version "$version" || release_refuse "\`$version\` is no release version: a release is MAJOR.MINOR.PATCH, each a number with no
leading zero.

  Fix: run the release with a version such as 0.2.0."
  if [ -n "$(git status --porcelain --untracked-files=normal)" ]; then
    release_refuse "The working tree holds changes no commit holds, so the tag would name a commit that is
not what CI passed.

  Fix: commit or set them aside (git status lists them), then run the release again."
  fi
  branch="$(git symbolic-ref --quiet --short HEAD || true)"
  [ "$branch" = main ] || release_refuse "The release stands on ${branch:-no branch}, and a release tags what is on \`main\`.

  Fix: check out \`main\` at the commit you mean to release, then run the release again."
  if ! git remote get-url "$remote" >/dev/null 2>&1; then
    release_refuse "No remote named \`$remote\`, the repository on Entire, so the tag would reach nobody.

  Fix: git remote add $remote <the repository's address on Entire>, then run the release again."
  elif ! answer="$(GIT_TERMINAL_PROMPT=0 git ls-remote "$remote" refs/heads/main 'refs/tags/v*' 2>&1)"; then
    release_refuse "Asking \`$remote\` for its main and its tags failed: $answer

  Fix: reach it, then run the release again."
  else
    main="$(printf '%s\n' "$answer" | awk '$2 == "refs/heads/main" { print $1 }')"
    [ "$main" = "$release_head" ] || release_refuse "This commit ($(printf '%s' "$release_head" | cut -c1-12)) is not the one \`$remote\`'s main is at ($(printf '%s' "${main:-none}" | cut -c1-12)).

  Fix: push main, or check out the commit \`$remote\` holds, then run the release again."
    entire_tag="$(printf '%s\n' "$answer" | awk -v ref="refs/tags/$tag" '$2 == ref { print $1 }')"
    here_tag="$(git rev-parse -q --verify "refs/tags/$tag" 2>/dev/null || true)"
    if [ -n "$entire_tag" ] && [ -z "$here_tag" ] && [ "$(printf '%s\n' "$answer" | awk -v ref="refs/tags/$tag^{}" '$2 == ref { print $1 }')" = "$release_head" ]; then
      release_refuse "\`$remote\` holds $tag on this commit, and this clone does not: a release that stopped here, or ran from another clone.

  Fix: git fetch $remote refs/tags/$tag:refs/tags/$tag, then run the release again: it goes on from there."
    elif [ -n "$entire_tag" ] && [ "$entire_tag" != "$here_tag" ]; then
      release_refuse "\`$remote\` holds $tag at another object than this clone, so $version was released from elsewhere.

  Fix: release a version past $version."
    fi
    if [ -n "$here_tag" ] && [ "$(git rev-parse "$tag^{commit}")" != "$release_head" ]; then
      release_refuse "$tag is tagged here on $(git rev-parse --short=12 "$tag^{commit}"), not on this commit.

  Fix: release a version past $version."
    fi
    # The mirror holds only what mirror.yml pushed from Entire, and never moves a tag: one it holds
    # that Entire does not, or at another object, would stop the release after its push.
    mirror_tag="$(release_remote_tag "$RELEASE_MIRROR" "$tag")"
    if [ -n "$mirror_tag" ] && [ "$mirror_tag" != "$entire_tag" ]; then
      release_refuse "The mirror, $RELEASE_MIRROR, holds $tag at ${mirror_tag:0:12}, which \`$remote\` does not, and mirror.yml never moves a tag.

  Fix: compare them (git ls-remote $RELEASE_MIRROR refs/tags/$tag), then release a version past $version."
    fi
    if release_is_version "$version"; then
      for existing in $( { git tag --list 'v*'; printf '%s\n' "$answer" | sed -n 's|.*refs/tags/||p'; GIT_TERMINAL_PROMPT=0 git ls-remote --tags --refs "$RELEASE_MIRROR" 2>/dev/null | sed -n 's|.*refs/tags/||p'; } | sed -n 's/^v//p' | sort -u); do
        release_is_version "$existing" || continue
        if [ "$existing" != "$version" ] && ! release_newer "$version" "$existing"; then
          release_refuse "v$existing is tagged already, and $version is not newer, so the release would go behind it.

  Fix: release a version past $existing."
          break
        fi
      done
    fi
  fi
  refusal="$(release_ci_refusal "$release_head")"
  [ -z "$refusal" ] || release_refuse "$refusal"
}

# release_by_a_person: a release is a person's, so an agent's shell is refused, whatever terminal it
# was given (`script` gives one to anything): Claude Code sets CLAUDECODE in every shell it starts.
release_by_a_person() {
  [ -z "${CLAUDECODE:-}" ] || die "This shell is an agent's (CLAUDECODE is set), and a release is a person's." "Run it yourself, from your own terminal."
}

# release_confirm <what> <yes>: asks before the release does anything, unless <yes> is 1. Never in
# an agent's shell, with --yes or without.
release_confirm() {
  local answer
  release_by_a_person
  [ "$2" -eq 1 ] && return 0
  [ -t 0 ] || die "The release asks before it does anything, and nothing can answer here." "Run it from a terminal, or pass --yes once you have read what it does."
  printf 'Release %s? [y/N] ' "$1"
  read -r answer
  case "$answer" in
    y | Y | yes | Yes) ;;
    *) die "The release of $1 was not made: nothing was tagged, pushed or published." ;;
  esac
}

# release_ci <commit>: the status of this repository's latest CI run on <commit>, as Depot lists
# it, in $release_ci: finished, failed, cancelled, queued or running; none where its CI never ran
# there; unknown where depot cannot say, and $release_ci_why says why. $release_ci_id is the run.
release_ci() {
  release_ci=unknown
  release_ci_id=""
  release_ci_why=""
  local depot out
  depot="$(command -v depot 2>/dev/null || mise which depot 2>/dev/null || true)"
  if [ -z "$depot" ]; then
    release_ci_why="depot is not installed (mise.toml pins it: mise install)"
    return 0
  fi
  # Every status: with none named, depot lists queued and running runs alone.
  if ! out="$("$depot" ci run list --repo "$RELEASE_KEY" --sha "$1" --status queued --status running --status finished --status failed --status cancelled -n 50 --output json </dev/null 2>&1)"; then
    release_ci_why="depot cannot list the CI runs: $(printf '%s\n' "$out" | sed -n 1p)"
    return 0
  fi
  # Depot lists a run for each push, the latest first, and others on the same commit: a tag pushed
  # there (mirror.yml alone), `depot ci run` on uncommitted work, a schedule. CI's is the latest
  # one a push of a branch started.
  out="$(printf '%s\n' "$out" | awk 'BEGIN { RS = "}" } /"ref": *"refs\/heads\// && /"trigger": *"push"/ { print; exit }' | tr ',{' '\n\n')"
  release_ci="$(printf '%s\n' "$out" | sed -n 's/^[[:space:]]*"status":[[:space:]]*"\([a-z_]*\)".*/\1/p' | sed -n 1p)"
  release_ci_id="$(printf '%s\n' "$out" | sed -n 's/^[[:space:]]*"run_id":[[:space:]]*"\([^"]*\)".*/\1/p' | sed -n 1p)"
  [ -n "$release_ci" ] || release_ci=none
}

# release_ci_refusal <commit>: what stands in the way where CI did not finish green on <commit>,
# and what to do; nothing where it did.
release_ci_refusal() {
  local short
  short="$(printf '%s' "$1" | cut -c1-12)"
  release_ci "$1"
  case "$release_ci" in
    finished) ;;
    queued | running)
      printf '%s\n' "CI is $release_ci on $short (run $release_ci_id), and a release tags only a commit CI passed.

  Fix: wait for it (depot ci run list --repo $RELEASE_KEY --sha $1), then run the release again."
      ;;
    failed | cancelled)
      printf '%s\n' "CI $release_ci on $short (run $release_ci_id), and a release tags only a commit CI passed.

  Fix: read it (depot ci logs $release_ci_id), fix what it reports in a commit of its own, push it,
  then run the release again."
      ;;
    none)
      printf '%s\n' "CI never ran on $short, and a release tags only a commit CI passed.

  Fix: push main, which runs CI, wait for it to pass, then run the release again."
      ;;
    *)
      printf '%s\n' "Whether CI passed on $short is not known: $release_ci_why.

  Fix: make depot answer (depot login), then run the release again."
      ;;
  esac
}

# release_remote_tag <remote or address> <tag>: the object it lists for the tag, nothing where it
# lists none or cannot be asked. An address asked over https never prompts for a login.
release_remote_tag() {
  GIT_TERMINAL_PROMPT=0 git ls-remote "$1" "refs/tags/$2" 2>/dev/null | awk 'NR == 1 { print $1 }' || true
}

# release_notes <changelog> <version>: the text of the version's section, headed
# "## [<version>]" or "## [v<version>]", without its heading and its blank lines at either end.
release_notes() {
  awk -v version="$2" '
    BEGIN { gsub(/\./, "\\.", version); heading = "^## \\[v?" version "\\]( |$)" }
    $0 ~ heading { inside = 1; next }
    inside && /^## \[/ { exit }
    inside { lines[++n] = $0 }
    END {
      first = 1
      while (first <= n && lines[first] ~ /^[[:space:]]*$/) first++
      last = n
      while (last >= first && lines[last] ~ /^[[:space:]]*$/) last--
      for (i = first; i <= last; i++) print lines[i]
    }
  ' "$1"
}

# release_dated <changelog> <version>: whether the changelog holds the version's dated section,
# "## [<version>] - YYYY-MM-DD", as `mise run version` writes it.
release_dated() {
  awk -v version="$2" '
    BEGIN { gsub(/\./, "\\.", version); heading = "^## \\[v?" version "\\] - [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9][[:space:]]*$"; missing = 1 }
    $0 ~ heading { missing = 0; exit }
    END { exit missing }
  ' "$1"
}

# release_date_unreleased <changelog> <version>: the changelog with its `## [Unreleased]` notes
# moved under "## [<version>] - <today>", an empty `## [Unreleased]` left above them, on standard
# output. The changelog as it is where it holds the dated section already.
release_date_unreleased() {
  if release_dated "$1" "$2"; then
    cat "$1"
    return 0
  fi
  awk -v version="$2" -v date="$(date -u +%Y-%m-%d)" '
    function emit(more,   first, last, i) {
      first = 1
      while (first <= n && lines[first] ~ /^[[:space:]]*$/) first++
      last = n
      while (last >= first && lines[last] ~ /^[[:space:]]*$/) last--
      print ""
      print "## [" version "] - " date
      print ""
      for (i = first; i <= last; i++) print lines[i]
      if (more) print ""
    }
    /^## \[Unreleased\][[:space:]]*$/ { print; inside = 1; next }
    inside && /^## \[/ { emit(1); inside = 0 }
    inside { lines[++n] = $0; next }
    { print }
    END { if (inside) emit(0) }
  ' "$1"
}

# release_tag <tag> <title> <notes file>: the annotated tag on HEAD, its message the title, a blank
# line and the notes (the version's CHANGELOG.md section, as release_notes reads it), kept verbatim:
# `git tag` drops each line that starts with # otherwise. mirror.yml makes the tag's GitHub
# Release from that message past its first line. A tag already here is kept where it names HEAD,
# and refused where it does not.
release_tag() {
  local at
  if at="$(git rev-parse -q --verify "refs/tags/$1^{commit}" 2>/dev/null)"; then
    [ "$at" = "$(git rev-parse HEAD)" ] || die "$1 is tagged here on $(printf '%s' "$at" | cut -c1-12), and the release is of $(git rev-parse --short=12 HEAD)." \
      "Where that tag reached no remote, delete it here (git tag -d $1), then run the release again."
    ok "$1 is tagged here already, on this commit."
    return 0
  fi
  { printf '%s\n\n' "$2"; cat "$3"; } | git tag --annotate --cleanup=verbatim "$1" --file=-
  ok "Tagged $1 on $(git rev-parse --short=12 HEAD)."
}

# release_push_tag <remote> <tag>: the tag alone, pushed to Entire where it is not there yet. One
# Entire holds at another object is refused: a released tag is never moved.
release_push_tag() {
  local there here
  here="$(git rev-parse "refs/tags/$2")"
  there="$(release_remote_tag "$1" "$2")"
  if [ "$there" = "$here" ]; then
    ok "$1 holds $2 already."
    return 0
  fi
  [ -z "$there" ] || die "$1 holds $2 at another object than the tag here, and a released tag is never moved." \
    "Compare them (git ls-remote $1 refs/tags/$2), then release a version past this one."
  git push "$1" "refs/tags/$2" || die "Pushing $2 to $1 failed: the tag is made here alone." \
    "Once $1 is reachable, run the release again: it pushes the tag and goes on."
  ok "Pushed $2 to $1."
}

# release_wait_mirror <tag>: waits until the mirror lists the tag as it is here, mirror.yml pushing
# it there from Entire: RELEASE_WAIT_SECONDS at most (600), asking every RELEASE_POLL_SECONDS (15).
release_wait_mirror() {
  local made listed waited=0 limit="${RELEASE_WAIT_SECONDS:-600}" poll="${RELEASE_POLL_SECONDS:-15}"
  made="$(git rev-parse "refs/tags/$1")"
  info "Waiting for the mirror, $RELEASE_MIRROR, to list $1: mirror.yml pushes it there from Entire, then makes its GitHub Release."
  while :; do
    listed="$(release_remote_tag "$RELEASE_MIRROR" "$1")"
    if [ -n "$listed" ]; then
      [ "$listed" = "$made" ] || die "The mirror, $RELEASE_MIRROR, lists $1 at another object than the tag here, and mirror.yml never moves a tag." \
        "Read its last runs: depot ci run list --repo $RELEASE_KEY"
      ok "The mirror lists $1."
      release_wait_github_release "$1"
      return 0
    fi
    [ "$waited" -lt "$limit" ] || break
    sleep "$poll"
    # A poll of 0 (a test's) still counts a second, so the wait ends.
    waited=$((waited + (poll > 0 ? poll : 1)))
  done
  die "The mirror, $RELEASE_MIRROR, does not list $1 after $waited seconds; the tag is on Entire." \
    "mirror.yml pushes it there: depot ci run list --repo $RELEASE_KEY shows its runs, and depot ci logs <run> the one for $1." \
    "Once it has run, run the release again: it finds the tag on Entire and waits for the mirror alone."
}

# release_wait_github_release <tag>: waits until GitHub lists the tag's Release, which mirror.yml
# makes once the tag is on the mirror, asking its public API every 20 seconds, five minutes at most.
# A mirror that is no GitHub repository (a test's stand-in) has none to wait for.
release_wait_github_release() {
  local api waited=0
  case "$RELEASE_MIRROR" in https://github.com/*) ;; *) return 0 ;; esac
  command -v curl >/dev/null 2>&1 || { warn "curl is not on PATH, so whether GitHub made the Release of $1 is not checked."; return 0; }
  api="https://api.github.com/repos/${RELEASE_MIRROR#https://github.com/}/releases/tags/$1"
  while ! curl -fsS -o /dev/null "$api" 2>/dev/null; do
    [ "$waited" -lt 300 ] || die "GitHub lists no Release of $1 after five minutes, though the mirror holds the tag." \
      "mirror.yml makes it: depot ci run list --repo $RELEASE_KEY shows its runs; MIRROR_GITHUB_TOKEN may have expired or lack the repository." \
      "Once it has run, run the release again: it finds everything else done and waits for the Release alone."
    sleep 20
    waited=$((waited + 20))
  done
  ok "GitHub has the Release of $1: $RELEASE_MIRROR/releases/tag/$1"
}

# release_ran <step> <commit>: whether <step> passed here on <commit>, as release_record wrote it,
# so a release run again does not run its longest suites twice on one commit.
release_ran() { [ -f "$(release_git_dir)/mountaya/release/$1-$2" ]; }
release_record() {
  mkdir -p "$(release_git_dir)/mountaya/release"
  date -u +%Y-%m-%dT%H:%M:%SZ >"$(release_git_dir)/mountaya/release/$1-$2"
}

# release_lock: held while the release runs. gate (.agents/siblings) stops on it, since its suites
# and a release's compete for the same machine. It is made in one step, so two releases started at
# once cannot both take it, and a lock whose process is gone is taken over.
release_lock() {
  local lock pid tries=0
  release_by_a_person
  lock="$(release_git_dir)/mountaya/release.lock"
  mkdir -p "$(dirname "$lock")"
  while ! (set -C && printf 'pid=%s\nrelease=%s\n' "$$" "$RELEASE_REPO" >"$lock") 2>/dev/null; do
    pid="$(sed -n 's/^pid=//p' "$lock" 2>/dev/null || true)"
    if [ -n "$pid" ] && [ "$pid" != "$$" ] && kill -0 "$pid" 2>/dev/null; then
      die "Another release of $RELEASE_REPO is running (process $pid)." "Let it finish, then run this one again."
    fi
    tries=$((tries + 1))
    [ "$tries" -lt 3 ] || die "$lock cannot be made." "Check that $(dirname "$lock") is writable, then run the release again."
    rm -f "$lock"
  done
  RELEASE_LOCK="$lock"
  trap 'rm -f "$RELEASE_LOCK"' EXIT
}

# release_keychain <NAME>: the value the Keychain keeps for NAME, nothing where it keeps none. A
# value release_secret kept is base64, "b64*<n>:" then its first chunk, the rest in NAME.2 to
# NAME.<n>: security reads a command a line, 4096 bytes at most. Any other is taken as it is.
release_keychain() {
  local first rest="" count index=2 chunk
  command -v security >/dev/null 2>&1 || return 0
  first="$(security find-generic-password -s "$RELEASE_KEYCHAIN_SERVICE" -a "$1" -w 2>/dev/null)" || return 0
  case "$first" in
    'b64*'*:*)
      count="${first#b64\*}"
      count="${count%%:*}"
      rest="${first#*:}"
      while [ "$index" -le "$count" ]; do
        chunk="$(security find-generic-password -s "$RELEASE_KEYCHAIN_SERVICE" -a "$1.$index" -w 2>/dev/null)" || return 0
        rest="$rest$chunk"
        index=$((index + 1))
      done
      printf '%s' "$rest" | base64 -d 2>/dev/null || printf '%s' "$rest" | base64 -D
      ;;
    *) printf '%s' "$first" ;;
  esac
}

# release_keep <NAME> <value>: the value kept in the Keychain, as release_keychain reads it. security
# reads its commands from standard input here, so the value never stands on a command line.
release_keep() {
  local encoded count index=1 account prefix
  encoded="$(printf '%s' "$2" | base64 | tr -d '\n')"
  count=$(((${#encoded} + 2999) / 3000))
  {
    while [ "$index" -le "$count" ]; do
      if [ "$index" -eq 1 ]; then account="$1" prefix="b64*$count:"; else account="$1.$index" prefix=""; fi
      printf 'add-generic-password -U -s %s -a %s -w %s%s\n' "$RELEASE_KEYCHAIN_SERVICE" "$account" "$prefix" "$(printf '%s' "$encoded" | cut -c "$(((index - 1) * 3000 + 1))-$((index * 3000))")"
      index=$((index + 1))
    done
  } | security -i >/dev/null 2>&1
}

# release_forget_hint <NAME>: the command that forgets what the Keychain keeps for NAME, chunks included.
release_forget_hint() {
  printf 'for account in %s %s.2 %s.3 %s.4; do security delete-generic-password -s %s -a "$account"; done' "$1" "$1" "$1" "$1" "$RELEASE_KEYCHAIN_SERVICE"
}

# release_secret <NAME> <what it is> [<check> [multiline]]: exports NAME, from the environment, else
# the macOS Keychain (service $RELEASE_KEYCHAIN_SERVICE, account NAME), else asked for with the input
# hidden where a terminal is attached. A multiline value is an armored key, read whole, through its
# "-----END ... -----" line, whatever blank lines it holds. <check>, a function given the value,
# says whether it works, and prints why where it does not. A value asked for that works is offered
# to be kept in the Keychain. Nothing is written to a file, and the value never stands on a command
# line.
release_secret() {
  local name="$1" what="$2" check="${3:-}" multiline="${4:-}" value="" from=environment line
  value="$(printenv "$name" || true)"
  if [ -z "$value" ]; then
    value="$(release_keychain "$name")"
    [ -z "$value" ] || from=Keychain
  fi
  if [ -z "$value" ]; then
    [ -t 0 ] || die "$name, $what, is in neither the environment nor the Keychain, and nothing can ask for it here." \
      "Run the release from a terminal: it asks for it, and offers to keep it in the Keychain."
    if [ -n "$multiline" ]; then
      printf '%s, %s (paste it whole: it ends at its -----END line): ' "$name" "$what" >&2
    else
      printf '%s, %s: ' "$name" "$what" >&2
    fi
    # Echo comes back however the prompt ends, Ctrl-C included.
    trap 'stty echo; exit 130' INT TERM
    stty -echo
    if [ -n "$multiline" ]; then
      while IFS= read -r line; do
        value="$value$line
"
        case "$line" in -----END*-----) break ;; esac
      done
    else
      IFS= read -r value || true
    fi
    stty echo
    trap - INT TERM
    printf '\n' >&2
    [ -n "$value" ] || die "No value was given for $name, $what." "Run the release again, and give it."
    from=prompt
  fi
  if [ -n "$check" ] && ! "$check" "$value"; then
    if [ "$from" = Keychain ]; then
      die "$name, $what, from the Keychain, does not work: the line above says why." \
        "Forget it ($(release_forget_hint "$name")), then run the release again, which asks for it."
    fi
    die "$name, $what, from the $from, does not work: the line above says why." "Run the release again with the right value."
  fi
  export "$name=$value"
  if [ "$from" = prompt ] && command -v security >/dev/null 2>&1; then
    printf 'Keep %s in the Keychain (%s), so the next release need not ask? [y/N] ' "$name" "$RELEASE_KEYCHAIN_SERVICE" >&2
    read -r line || line=""
    case "$line" in
      y | Y | yes | Yes)
        if release_keep "$name" "$value"; then ok "Kept $name in the Keychain."; else warn "The Keychain did not keep $name: the next release asks for it again."; fi
        ;;
    esac
  fi
}
